#include <iostream>
#include <string>
using namespace std;

class Cat {
    string name;
protected:
    int fish;
public:
    Cat(string n, int f) : name(n), fish(f) {}
    void showName() const {
        cout << "本喵是" << name << "喵" << endl;
    }
};

class Kitten : public Cat {
public:
    Kitten(string n, int f) : Cat(n, f) {}
    void eat() {
        fish = fish + 1;
        cout << "吃了一条，现在 " << fish << " 条" << endl;
    }
};

int main() {
    int f = 0;
    cin >> f;

    Kitten k("{name}", f);
    k.showName();
    k.eat();
    return 0;
}
